/**
 * Main Cloudflare Worker entry point
 * Routes webhook requests to appropriate handlers
 */

import { Env } from './types';
import { AudioWebhookHandler } from './handlers/audioWebhook';
import { TranscriptionWebhookHandler } from './handlers/transcriptionWebhook';

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    // Add CORS headers
    const corsHeaders = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
    };

    // Handle CORS preflight
    if (request.method === 'OPTIONS') {
      return new Response(null, {
        status: 204,
        headers: corsHeaders,
      });
    }

    try {
      const url = new URL(request.url);
      const path = url.pathname;

      // Route to appropriate handler
      switch (path) {
        case '/webhook/audio':
          return await handleAudioWebhook(request, env, corsHeaders);

        case '/webhook/transcription':
          return await handleTranscriptionWebhook(request, env, corsHeaders);

        case '/health':
          return handleHealthCheck(corsHeaders);

        case '/':
          return handleRoot(corsHeaders);

        default:
          return new Response(
            JSON.stringify({
              error: 'Not Found',
              message: 'The requested endpoint does not exist',
              availableEndpoints: [
                '/webhook/audio',
                '/webhook/transcription',
                '/health',
              ],
            }),
            {
              status: 404,
              headers: {
                ...corsHeaders,
                'Content-Type': 'application/json',
              },
            }
          );
      }
    } catch (error) {
      console.error('Worker error:', error);
      return new Response(
        JSON.stringify({
          error: 'Internal Server Error',
          message: error instanceof Error ? error.message : 'Unknown error',
        }),
        {
          status: 500,
          headers: {
            ...corsHeaders,
            'Content-Type': 'application/json',
          },
        }
      );
    }
  },
};

/**
 * Handle audio webhook requests
 */
async function handleAudioWebhook(
  request: Request,
  env: Env,
  corsHeaders: Record<string, string>
): Promise<Response> {
  if (request.method !== 'POST') {
    return new Response(
      JSON.stringify({ error: 'Method not allowed. Use POST.' }),
      {
        status: 405,
        headers: {
          ...corsHeaders,
          'Content-Type': 'application/json',
        },
      }
    );
  }

  // Validate required environment variables
  if (!env.GROQ_API_KEY || !env.SUPERMEMORY_API_KEY) {
    return new Response(
      JSON.stringify({
        error: 'Configuration Error',
        message: 'Missing required API keys. Please configure GROQ_API_KEY and SUPERMEMORY_API_KEY.',
      }),
      {
        status: 500,
        headers: {
          ...corsHeaders,
          'Content-Type': 'application/json',
        },
      }
    );
  }

  const handler = new AudioWebhookHandler(env);
  const response = await handler.handleRequest(request);

  // Add CORS headers to response
  const newHeaders = new Headers(response.headers);
  Object.entries(corsHeaders).forEach(([key, value]) => {
    newHeaders.set(key, value);
  });

  return new Response(response.body, {
    status: response.status,
    headers: newHeaders,
  });
}

/**
 * Handle transcription webhook requests
 */
async function handleTranscriptionWebhook(
  request: Request,
  env: Env,
  corsHeaders: Record<string, string>
): Promise<Response> {
  if (request.method !== 'POST') {
    return new Response(
      JSON.stringify({ error: 'Method not allowed. Use POST.' }),
      {
        status: 405,
        headers: {
          ...corsHeaders,
          'Content-Type': 'application/json',
        },
      }
    );
  }

  // Validate required environment variables
  if (!env.SUPERMEMORY_API_KEY) {
    return new Response(
      JSON.stringify({
        error: 'Configuration Error',
        message: 'Missing required API key. Please configure SUPERMEMORY_API_KEY.',
      }),
      {
        status: 500,
        headers: {
          ...corsHeaders,
          'Content-Type': 'application/json',
        },
      }
    );
  }

  const handler = new TranscriptionWebhookHandler(env);
  const response = await handler.handleRequest(request);

  // Add CORS headers to response
  const newHeaders = new Headers(response.headers);
  Object.entries(corsHeaders).forEach(([key, value]) => {
    newHeaders.set(key, value);
  });

  return new Response(response.body, {
    status: response.status,
    headers: newHeaders,
  });
}

/**
 * Handle health check requests
 */
function handleHealthCheck(corsHeaders: Record<string, string>): Response {
  return new Response(
    JSON.stringify({
      status: 'healthy',
      service: 'never-be-alone-webhook-server',
      timestamp: new Date().toISOString(),
      endpoints: {
        audio: '/webhook/audio',
        transcription: '/webhook/transcription',
      },
    }),
    {
      status: 200,
      headers: {
        ...corsHeaders,
        'Content-Type': 'application/json',
      },
    }
  );
}

/**
 * Handle root requests
 */
function handleRoot(corsHeaders: Record<string, string>): Response {
  return new Response(
    JSON.stringify({
      name: 'Never Be Alone - Webhook Server',
      version: '1.0.0',
      description: 'Cloudflare Workers webhook server for Omi wearable audio streaming and transcription',
      endpoints: [
        {
          path: '/webhook/audio',
          method: 'POST',
          description: 'Receive audio bytes from Omi device, convert to WAV, transcribe with Groq Whisper, and store in Supermemory',
          parameters: {
            query: {
              uid: 'User ID (required)',
              sample_rate: 'Audio sample rate in Hz (default: 16000)',
            },
            body: 'Raw audio bytes (application/octet-stream)',
          },
        },
        {
          path: '/webhook/transcription',
          method: 'POST',
          description: 'Receive pre-transcribed text from Omi device and store in Supermemory',
          parameters: {
            query: {
              uid: 'User ID (required)',
            },
            body: {
              segments: 'Array of transcription segments (optional)',
              transcript: 'Full transcript text (optional)',
              session_id: 'Session identifier (optional)',
            },
          },
        },
        {
          path: '/health',
          method: 'GET',
          description: 'Health check endpoint',
        },
      ],
      documentation: 'https://github.com/Parth0248/never-be-alone',
    }),
    {
      status: 200,
      headers: {
        ...corsHeaders,
        'Content-Type': 'application/json',
      },
    }
  );
}
