/**
 * Supermemory API client for universal storage
 */

import { SupermemoryAddResponse, SupermemorySearchResponse } from '../types';

export interface SupermemoryContent {
  text: string;
  metadata?: {
    uid?: string;
    timestamp?: number;
    source?: string;
    audioChunkId?: string;
    transcriptionId?: string;
    duration?: number;
    [key: string]: any;
  };
}

export class SupermemoryClient {
  private apiKey: string;
  private baseUrl: string;
  private sessionId: string | null = null;
  private sessionInitPromise: Promise<void> | null = null;

  constructor(apiKey: string, baseUrl: string = 'https://api.supermemory.ai/') {
    this.apiKey = apiKey;
    this.baseUrl = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
  }

  /**
   * Initialize MCP session
   * @returns Promise that resolves when session is initialized
   */
  private async initializeSession(): Promise<void> {
    if (this.sessionId) {
      return; // Already initialized
    }

    if (this.sessionInitPromise) {
      return this.sessionInitPromise; // Wait for existing initialization
    }

    this.sessionInitPromise = (async () => {
      try {
        const payload = {
          jsonrpc: '2.0',
          id: 1,
          method: 'initialize',
          params: {
            protocolVersion: '2024-11-05',
            capabilities: {
              roots: { listChanged: true },
              sampling: {},
            },
            clientInfo: {
              name: 'never-be-alone-webhook',
              version: '1.0.0',
            },
          },
        };

        const response = await fetch(`${this.baseUrl}mcp`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${this.apiKey}`,
            'Accept': 'application/json, text/event-stream',
          },
          body: JSON.stringify(payload),
        });

        if (!response.ok) {
          throw new Error(`MCP init failed (${response.status}): ${await response.text()}`);
        }

        // Generate a session ID (MCP typically returns this in headers or response)
        this.sessionId = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        console.log('MCP session initialized:', this.sessionId);
      } catch (error) {
        console.error('Failed to initialize MCP session:', error);
        this.sessionInitPromise = null;
        throw error;
      }
    })();

    return this.sessionInitPromise;
  }

  /**
   * Ensure session is initialized before making requests
   */
  private async ensureSession(): Promise<string> {
    if (!this.sessionId) {
      await this.initializeSession();
    }
    return this.sessionId!;
  }

  /**
   * Add content to Supermemory using MCP protocol
   * @param content - Content to store
   * @returns Response with success status and ID
   */
  async addMemory(content: SupermemoryContent): Promise<SupermemoryAddResponse> {
    try {
      // Ensure MCP session is initialized
      const sessionId = await this.ensureSession();

      // Use MCP protocol with JSON-RPC format
      const payload = {
        jsonrpc: '2.0',
        id: Date.now(),
        method: 'tools/call',
        params: {
          name: 'addMemory',
          arguments: {
            thingToRemember: content.text,
            ...(content.metadata && Object.keys(content.metadata).length > 0
              ? { metadata: JSON.stringify(content.metadata) }
              : {})
          },
        },
      };

      const response = await fetch(`${this.baseUrl}mcp`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.apiKey}`,
          'Accept': 'application/json, text/event-stream',
          'Mcp-Session-Id': sessionId,
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(
          `Supermemory API error (${response.status}): ${errorText}`
        );
      }

      const result = await response.json();

      // Handle MCP response format
      if (result.error) {
        throw new Error(`MCP error: ${result.error.message || JSON.stringify(result.error)}`);
      }

      return {
        success: true,
        id: result.result?.id || result.id || `memory_${Date.now()}`,
      };
    } catch (error) {
      console.error('Supermemory add error:', error);
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Search Supermemory for relevant content using MCP protocol
   * @param query - Search query
   * @param options - Search options
   * @returns Search results
   */
  async search(
    query: string,
    options?: {
      maxResults?: number;
      uid?: string;
      metadata?: Record<string, any>;
    }
  ): Promise<SupermemorySearchResponse> {
    try {
      // Use MCP protocol with JSON-RPC format
      const payload = {
        jsonrpc: '2.0',
        id: Date.now(),
        method: 'tools/call',
        params: {
          name: 'search',
          arguments: {
            informationToGet: query,
            ...(options?.maxResults && { max_results: options.maxResults }),
          },
        },
      };

      const response = await fetch(`${this.baseUrl}mcp`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.apiKey}`,
          'Accept': 'application/json, text/event-stream',
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(
          `Supermemory API error (${response.status}): ${errorText}`
        );
      }

      const result = await response.json();

      // Handle MCP response format
      if (result.error) {
        console.error('MCP search error:', result.error);
        return { results: [] };
      }

      // Parse MCP response - results are in result.content array
      const content = result.result?.content || [];
      const results = content.map((item: any) => ({
        content: item.text || item.content || '',
        score: 1.0,
        metadata: item.metadata || {},
      }));

      return { results };
    } catch (error) {
      console.error('Supermemory search error:', error);
      return { results: [] };
    }
  }

  /**
   * Store transcription in Supermemory
   * @param transcription - Transcription text
   * @param metadata - Additional metadata
   * @returns Response with success status
   */
  async storeTranscription(
    transcription: string,
    metadata: {
      uid: string;
      timestamp: number;
      source: 'omi' | 'groq';
      audioChunkId?: string;
      transcriptionId?: string;
      duration?: number;
    }
  ): Promise<SupermemoryAddResponse> {
    return this.addMemory({
      text: transcription,
      metadata: {
        ...metadata,
        type: 'transcription',
        createdAt: new Date().toISOString(),
      },
    });
  }

  /**
   * Store audio metadata in Supermemory
   * @param audioInfo - Audio chunk information
   * @returns Response with success status
   */
  async storeAudioMetadata(audioInfo: {
    uid: string;
    chunkId: string;
    sampleRate: number;
    duration: number;
    timestamp: number;
    format: string;
  }): Promise<SupermemoryAddResponse> {
    return this.addMemory({
      text: `Audio chunk ${audioInfo.chunkId} from user ${audioInfo.uid}`,
      metadata: {
        ...audioInfo,
        type: 'audio_metadata',
        createdAt: new Date().toISOString(),
      },
    });
  }

  /**
   * Batch store multiple transcriptions
   * @param transcriptions - Array of transcriptions to store
   * @returns Array of responses
   */
  async batchStoreTranscriptions(
    transcriptions: Array<{
      text: string;
      metadata: SupermemoryContent['metadata'];
    }>
  ): Promise<SupermemoryAddResponse[]> {
    const promises = transcriptions.map(t =>
      this.addMemory({ text: t.text, metadata: t.metadata })
    );

    try {
      return await Promise.all(promises);
    } catch (error) {
      console.error('Batch store error:', error);
      throw error;
    }
  }

  /**
   * Get transcription history for a user
   * @param uid - User ID
   * @param maxResults - Maximum number of results
   * @returns Search results with user's transcription history
   */
  async getTranscriptionHistory(
    uid: string,
    maxResults: number = 50
  ): Promise<SupermemorySearchResponse> {
    return this.search(`transcriptions for user ${uid}`, {
      maxResults,
      uid,
    });
  }

  /**
   * Store with retry logic
   * @param content - Content to store
   * @param maxRetries - Maximum number of retry attempts
   * @param retryDelay - Delay between retries in milliseconds
   * @returns Response with success status
   */
  async addMemoryWithRetry(
    content: SupermemoryContent,
    maxRetries: number = 3,
    retryDelay: number = 1000
  ): Promise<SupermemoryAddResponse> {
    let lastError: string | null = null;

    for (let attempt = 0; attempt < maxRetries; attempt++) {
      const result = await this.addMemory(content);

      if (result.success) {
        return result;
      }

      lastError = result.error || null;
      console.warn(
        `Store attempt ${attempt + 1} failed:`,
        lastError
      );

      if (attempt < maxRetries - 1) {
        // Wait before retrying (exponential backoff)
        await new Promise(resolve =>
          setTimeout(resolve, retryDelay * Math.pow(2, attempt))
        );
      }
    }

    return {
      success: false,
      error: `Failed to store after ${maxRetries} attempts: ${lastError}`,
    };
  }

  /**
   * Create a session summary from multiple transcriptions
   * @param uid - User ID
   * @param sessionId - Session identifier
   * @param startTime - Session start time
   * @param endTime - Session end time
   * @returns Response with session summary ID
   */
  async createSessionSummary(
    uid: string,
    sessionId: string,
    startTime: number,
    endTime: number
  ): Promise<SupermemoryAddResponse> {
    // Get all transcriptions in the time range
    const transcriptions = await this.search(
      `transcriptions for user ${uid} between ${startTime} and ${endTime}`,
      { uid, maxResults: 100 }
    );

    if (transcriptions.results.length === 0) {
      return {
        success: false,
        error: 'No transcriptions found for this session',
      };
    }

    // Combine all transcriptions
    const fullText = transcriptions.results
      .map(r => r.content)
      .join(' ');

    // Store session summary
    return this.addMemory({
      text: fullText,
      metadata: {
        uid,
        sessionId,
        startTime,
        endTime,
        type: 'session_summary',
        transcriptionCount: transcriptions.results.length,
        createdAt: new Date().toISOString(),
      },
    });
  }
}
