/**
 * Groq API client for Whisper-large-v3 transcription
 */

import { GroqTranscriptionResponse } from '../types';

export class GroqClient {
  private apiKey: string;
  private baseUrl: string = 'https://api.groq.com/openai/v1';

  constructor(apiKey: string) {
    this.apiKey = apiKey;
  }

  /**
   * Transcribe audio using Groq Whisper-large-v3
   * @param audioData - Audio data as ArrayBuffer (WAV format recommended)
   * @param options - Transcription options
   * @returns Transcription result
   */
  async transcribe(
    audioData: ArrayBuffer,
    options?: {
      language?: string;
      prompt?: string;
      temperature?: number;
      timestamp_granularities?: ('word' | 'segment')[];
    }
  ): Promise<GroqTranscriptionResponse> {
    try {
      // Create form data with audio file
      const formData = new FormData();
      const audioBlob = new Blob([audioData], { type: 'audio/wav' });
      formData.append('file', audioBlob, 'audio.wav');
      formData.append('model', 'whisper-large-v3');

      // Add optional parameters
      if (options?.language) {
        formData.append('language', options.language);
      }
      if (options?.prompt) {
        formData.append('prompt', options.prompt);
      }
      if (options?.temperature !== undefined) {
        formData.append('temperature', options.temperature.toString());
      }
      // Note: timestamp_granularities is not supported by Groq Whisper API
      // Removed to avoid 400 errors

      // Set response format to verbose JSON to get detailed segments
      formData.append('response_format', 'verbose_json');

      const response = await fetch(`${this.baseUrl}/audio/transcriptions`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${this.apiKey}`,
        },
        body: formData,
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(
          `Groq API error (${response.status}): ${errorText}`
        );
      }

      const result = await response.json() as GroqTranscriptionResponse;
      return result;
    } catch (error) {
      console.error('Groq transcription error:', error);
      throw new Error(
        `Failed to transcribe audio: ${error instanceof Error ? error.message : 'Unknown error'}`
      );
    }
  }

  /**
   * Transcribe audio with automatic language detection
   * @param audioData - Audio data as ArrayBuffer
   * @returns Transcription result with detected language
   */
  async transcribeWithLanguageDetection(
    audioData: ArrayBuffer
  ): Promise<GroqTranscriptionResponse> {
    return this.transcribe(audioData, {
      timestamp_granularities: ['segment'],
    });
  }

  /**
   * Batch transcribe multiple audio chunks
   * @param audioChunks - Array of audio data chunks
   * @param options - Transcription options
   * @returns Array of transcription results
   */
  async batchTranscribe(
    audioChunks: ArrayBuffer[],
    options?: {
      language?: string;
      prompt?: string;
      temperature?: number;
    }
  ): Promise<GroqTranscriptionResponse[]> {
    const promises = audioChunks.map(chunk =>
      this.transcribe(chunk, options)
    );

    try {
      return await Promise.all(promises);
    } catch (error) {
      console.error('Batch transcription error:', error);
      throw error;
    }
  }

  /**
   * Transcribe with retry logic
   * @param audioData - Audio data as ArrayBuffer
   * @param maxRetries - Maximum number of retry attempts
   * @param retryDelay - Delay between retries in milliseconds
   * @returns Transcription result
   */
  async transcribeWithRetry(
    audioData: ArrayBuffer,
    maxRetries: number = 3,
    retryDelay: number = 1000
  ): Promise<GroqTranscriptionResponse> {
    let lastError: Error | null = null;

    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        // Use temperature=0 for deterministic, accurate transcription
        return await this.transcribe(audioData, {
          temperature: 0,
        });
      } catch (error) {
        lastError = error instanceof Error ? error : new Error('Unknown error');
        console.warn(
          `Transcription attempt ${attempt + 1} failed:`,
          lastError.message
        );

        if (attempt < maxRetries - 1) {
          // Wait before retrying (exponential backoff)
          await new Promise(resolve =>
            setTimeout(resolve, retryDelay * Math.pow(2, attempt))
          );
        }
      }
    }

    throw new Error(
      `Failed to transcribe after ${maxRetries} attempts: ${lastError?.message}`
    );
  }

  /**
   * Estimate audio duration from WAV data
   * @param audioData - WAV audio data
   * @returns Estimated duration in seconds
   */
  private estimateAudioDuration(audioData: ArrayBuffer): number {
    if (audioData.byteLength < 44) return 0;

    const view = new DataView(audioData);
    const sampleRate = view.getUint32(24, true);
    const byteRate = view.getUint32(28, true);
    const dataSize = audioData.byteLength - 44;

    return byteRate > 0 ? dataSize / byteRate : 0;
  }

  /**
   * Check if audio is long enough to transcribe (minimum 0.1 seconds)
   * @param audioData - Audio data to check
   * @returns True if audio is long enough
   */
  isAudioValid(audioData: ArrayBuffer): boolean {
    const duration = this.estimateAudioDuration(audioData);
    return duration >= 0.1 && audioData.byteLength > 44;
  }
}
